{
  "packet_id": "H6-T01-2",
  "claim_id": "C009",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C009.component",
    "value": "Replay fidelity must be demonstrated rather than assumed.",
    "scope": "Replay proposed for the selected late case; no fidelity criterion is specified.",
    "provenance": {
      "refs": [
        {"source_id": "P007", "role": "SUPPORT"},
        {"source_id": "P006", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly requires demonstrated fidelity for the selected case's replay without specifying a fidelity criterion."
    }
  },
  "signal_basis": {
    "component_id": "C009.signal_basis",
    "value": "A reduced replay repeatedly preserves lateness while specified further removals do not. Baseline reproduction and comparisons with reconstructed on-time bookings check replay adequacy, while agreement with recorded cases does not establish field effectiveness.",
    "scope": "Replay evidence for the selected late case, bounded by reconstruction assumptions and possible omitted operating conditions.",
    "provenance": {
      "refs": [
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P019", "role": "SUPPORT"},
        {"source_id": "P020", "role": "SUPPORT"},
        {"source_id": "P027", "role": "SUPPORT"},
        {"source_id": "P006", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the reproduction pattern, adequacy checks, and limits of replay evidence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C009.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is an execution requirement, not a conditional empirical inference."
    }
  },
  "rationale": "The claim is warranted as a methodological prerequisite: interpreting replay reductions as evidence about the selected case requires demonstrated fidelity. It does not assert that repeated reproduction itself establishes fidelity. Under the stipulated satisfaction of prerequisites, no additional empirical bridge is needed for this requirement.",
  "uncertainty": "The mapping leaves the fidelity criterion unspecified. That limits assessment of actual compliance, but does not undermine the stated requirement.",
  "anomalies": []
}
